<?php include 'includes/header.php'; require_admin(); $msg='';
if($_SERVER['REQUEST_METHOD']==='POST' && is_uploaded_file($_FILES['csv']['tmp_name'])){ $fh=fopen($_FILES['csv']['tmp_name'],'r'); $header=fgetcsv($fh); $count=0; while(($row=fgetcsv($fh))!==false){ $data=array_combine($header,$row); $d=$data['item_description']??$data['description']??''; if(!$d)continue; $s=$data['serial_number']??null; if($s==='')$s=null; $loc=$data['location']??''; $u=$data['uom']??'pcs'; $boh=(int)($data['boh']??0); $actual=(int)($data['actual_stock']??$boh); $stmt=$conn->prepare('INSERT INTO items(item_description,serial_number,location,uom,boh,actual_stock) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE item_description=VALUES(item_description),location=VALUES(location),uom=VALUES(uom),boh=VALUES(boh),actual_stock=VALUES(actual_stock)'); $stmt->bind_param('ssssii',$d,$s,$loc,$u,$boh,$actual); if($stmt->execute())$count++; } $msg="Imported $count rows."; }
?>
<h3>Excel/CSV Import</h3><?php if($msg):?><div class='alert alert-success'><?=$msg?></div><?php endif;?><div class='card cardx p-4'><p>Upload CSV saved from Excel. Required columns: item_description, serial_number, location, uom, boh, actual_stock.</p><form method='post' enctype='multipart/form-data'><input type='file' name='csv' accept='.csv' class='form-control mb-3' required><button class='btn btn-primary'>Import</button></form></div><?php include 'includes/footer.php'; ?>
